package com.anonyser.regear;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Round-trips the shareable export/import format and the name-collision helper, all without a running
 * client, so the "send someone your setup" path is locked in.
 */
public class RegearShareTest
{
	private final Gson gson = new Gson();

	private static RegearList sample(String name)
	{
		final RegearList l = new RegearList(name);
		l.enabled = true;
		l.visibleCount = 4;
		l.pattern = PatternPreset.Z;
		l.anchorSlot = 30;
		l.completion = CompletionBehavior.LOOP;
		final RegearItem whip = new RegearItem(4151);
		whip.quantity = 1;
		whip.note = "whip";
		whip.skipIfWorn = true;
		whip.alts.add(12006);
		l.items.add(whip);
		l.items.add(new RegearItem(2434, 3, null));
		l.resetLanes();
		return l;
	}

	@Test
	public void roundTripsEveryField()
	{
		final RegearList src = sample("Main");
		final List<RegearList> out = RegearShare.parse(RegearShare.export(Arrays.asList(src), gson), gson);
		assertEquals(1, out.size());
		final RegearList got = out.get(0);
		assertEquals("Main", got.name);
		assertTrue(got.enabled);
		assertEquals(4, got.visibleCount);
		assertEquals(PatternPreset.Z, got.pattern);
		assertEquals(30, got.anchorSlot);
		assertEquals(CompletionBehavior.LOOP, got.completion);
		assertEquals(2, got.items.size());
		assertEquals(4151, got.items.get(0).id);
		assertEquals("whip", got.items.get(0).note);
		assertTrue(got.items.get(0).skipIfWorn);
		assertEquals(Integer.valueOf(12006), got.items.get(0).alts.get(0));
		assertEquals(3, got.items.get(1).quantity);
	}

	@Test
	public void exportAllRoundTripsEveryList()
	{
		final List<RegearList> src = Arrays.asList(sample("A"), sample("B"), sample("C"));
		final List<RegearList> out = RegearShare.parse(RegearShare.export(src, gson), gson);
		assertEquals(3, out.size());
	}

	@Test
	public void tokenHasPrefixAndIsSingleLine()
	{
		final String token = RegearShare.export(Arrays.asList(sample("A")), gson);
		assertTrue(token.startsWith(RegearShare.PREFIX));
		assertFalse(token.contains("\n"));
	}

	@Test
	public void importedSetupStartsFresh()
	{
		final RegearList src = sample("Main");
		src.advanceLane(0, CompletionBehavior.STOP); // push progress off the start before exporting
		final RegearList got = RegearShare.parse(RegearShare.export(Arrays.asList(src), gson), gson).get(0);
		assertEquals(0, got.activeIndex(0));
	}

	@Test
	public void parseRejectsGarbage()
	{
		assertTrue(RegearShare.parse("not a real token", gson).isEmpty());
		assertTrue(RegearShare.parse("", gson).isEmpty());
		assertTrue(RegearShare.parse(null, gson).isEmpty());
	}

	@Test
	public void uniqueNameAvoidsCollisions()
	{
		final Set<String> taken = new HashSet<>(Arrays.asList("main", "main (2)"));
		assertEquals("Fresh", RegearShare.uniqueName("Fresh", taken));
		assertEquals("Main (3)", RegearShare.uniqueName("Main", taken));
	}
}

package com.anonyser.regear;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The client-free item flags behind Omit and Add blank space: an always-skipped entry is dropped from
 * the withdrawal cycle, and copying an entry keeps its flags.
 */
public class RegearItemTest
{
	@Test
	public void alwaysSkippedCoversBlankAndOmittedOnly()
	{
		assertFalse(new RegearItem(4151).alwaysSkipped());

		final RegearItem omitted = new RegearItem(4151);
		omitted.omitted = true;
		assertTrue(omitted.alwaysSkipped());

		final RegearItem blank = new RegearItem();
		blank.blank = true;
		assertTrue(blank.alwaysSkipped());

		// Skip-if-worn is conditional on the worn set, so it is NOT an unconditional skip.
		final RegearItem worn = new RegearItem(4151);
		worn.skipIfWorn = true;
		assertFalse(worn.alwaysSkipped());
	}

	@Test
	public void copyPreservesEveryFlag()
	{
		final RegearItem it = new RegearItem(4151, 3, "spec weapon");
		it.skipIfWorn = true;
		it.omitted = true;
		it.alts.add(4153);

		final RegearItem c = it.copy();
		assertEquals(4151, c.id);
		assertEquals(3, c.quantity);
		assertEquals("spec weapon", c.note);
		assertTrue(c.skipIfWorn);
		assertTrue(c.omitted);
		assertFalse(c.blank);
		assertTrue(c.alts.contains(4153));

		final RegearItem blank = new RegearItem();
		blank.blank = true;
		assertTrue(blank.copy().blank);
	}
}

package com.anonyser.regear;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Pure rotation / pattern / slot maths, exercised without a running client. These lock in the lane
 * behaviour described in the spec (1-, 2-, 3- and 4-item rotations, Z pattern, completion, overlap).
 */
public class RegearRotationTest
{
	private static RegearList list(PatternPreset pattern, int visible, int itemCount)
	{
		final RegearList l = new RegearList("t");
		l.pattern = pattern;
		l.visibleCount = visible;
		for (int i = 1; i <= itemCount; i++)
		{
			l.items.add(new RegearItem(i));
		}
		l.resetLanes();
		return l;
	}

	private static int activeId(RegearList l, int lane)
	{
		final RegearItem it = l.activeItem(lane);
		return it == null ? -1 : it.id;
	}

	@Test
	public void newListsDefaultToZPattern()
	{
		final RegearList fresh = new RegearList("fresh");
		assertEquals(PatternPreset.Z, fresh.pattern);
		// A brand-new list on pure defaults (Z, default visible count, default anchor) must fit the
		// grid -- Z is two columns wide, so the default anchor cannot sit on the last column.
		fresh.visibleCount = 3;
		assertTrue(fresh.fitsGrid());
		final RegearList loaded = new RegearList("loaded");
		loaded.pattern = null;
		loaded.normalize();
		assertEquals(PatternPreset.Z, loaded.pattern);
	}

	@Test
	public void threeLaneVerticalRotation()
	{
		final RegearList l = list(PatternPreset.VERTICAL, 3, 12);
		assertEquals(3, l.laneCount());
		assertEquals(1, activeId(l, 0));
		assertEquals(2, activeId(l, 1));
		assertEquals(3, activeId(l, 2));

		l.advanceLane(0, CompletionBehavior.STOP);
		assertEquals(4, activeId(l, 0));
		l.advanceLane(1, CompletionBehavior.STOP);
		assertEquals(5, activeId(l, 1));
		l.advanceLane(2, CompletionBehavior.STOP);
		assertEquals(6, activeId(l, 2));

		// Lane 0 walks 1,4,7,10 then empties.
		l.advanceLane(0, CompletionBehavior.STOP); // 7
		l.advanceLane(0, CompletionBehavior.STOP); // 10
		assertEquals(10, activeId(l, 0));
		l.advanceLane(0, CompletionBehavior.STOP); // past end
		assertNull(l.activeItem(0));
	}

	@Test
	public void singleSpotRotation()
	{
		final RegearList l = list(PatternPreset.SINGLE, 1, 4);
		assertEquals(1, l.laneCount());
		assertEquals(1, activeId(l, 0));
		l.advanceLane(0, CompletionBehavior.STOP);
		assertEquals(2, activeId(l, 0));
		l.advanceLane(0, CompletionBehavior.STOP);
		assertEquals(3, activeId(l, 0));
		l.advanceLane(0, CompletionBehavior.STOP);
		assertEquals(4, activeId(l, 0));
		l.advanceLane(0, CompletionBehavior.STOP);
		assertNull(l.activeItem(0));
	}

	@Test
	public void twoLaneRotation()
	{
		final RegearList l = list(PatternPreset.VERTICAL, 2, 8);
		assertEquals(1, activeId(l, 0));
		assertEquals(2, activeId(l, 1));
		l.advanceLane(0, CompletionBehavior.STOP);
		assertEquals(3, activeId(l, 0));
		l.advanceLane(1, CompletionBehavior.STOP);
		assertEquals(4, activeId(l, 1));
	}

	@Test
	public void fourLaneRotation()
	{
		final RegearList l = list(PatternPreset.VERTICAL, 4, 16);
		assertEquals(4, l.laneCount());
		assertEquals(1, activeId(l, 0));
		assertEquals(4, activeId(l, 3));
		l.advanceLane(3, CompletionBehavior.STOP);
		assertEquals(8, activeId(l, 3));
	}

	@Test
	public void sixLaneVertical()
	{
		final RegearList l = list(PatternPreset.VERTICAL, 6, 18);
		assertEquals(6, l.laneCount());
		assertEquals(1, activeId(l, 0));
		assertEquals(6, activeId(l, 5));
		l.advanceLane(5, CompletionBehavior.STOP);
		assertEquals(12, activeId(l, 5)); // lane 6 walks 6, 12, 18...
	}

	@Test
	public void zPatternOffsets()
	{
		final RegearList l = list(PatternPreset.Z, 4, 4);
		final List<PatternOffset> offs = l.effectiveOffsets();
		assertEquals(4, offs.size());
		assertEquals(new PatternOffset(0, 0), offs.get(0));
		assertEquals(new PatternOffset(0, 1), offs.get(1));
		assertEquals(new PatternOffset(1, 0), offs.get(2));
		assertEquals(new PatternOffset(1, 1), offs.get(3));
	}

	@Test
	public void customOffsetsDriveLanes()
	{
		final RegearList l = list(PatternPreset.CUSTOM, 3, 6);
		l.customOffsets.add(new PatternOffset(0, 0));
		l.customOffsets.add(new PatternOffset(0, 1));
		l.customOffsets.add(new PatternOffset(0, 2));
		l.resetLanes();
		assertEquals(3, l.laneCount());
		assertEquals(1, activeId(l, 0));
		assertEquals(3, activeId(l, 2));
	}

	@Test
	public void absoluteSlotsAndGridFit()
	{
		assertEquals(38, RegearList.defaultAnchorSlot(0));
		assertEquals(36, RegearList.defaultAnchorSlot(1));

		final RegearList v = list(PatternPreset.VERTICAL, 3, 6);
		v.anchorSlot = 39; // col 7, row 4
		assertEquals(39, v.absoluteSlot(0));
		assertEquals(47, v.absoluteSlot(1));
		assertEquals(55, v.absoluteSlot(2));
		assertTrue(v.fitsGrid());

		final RegearList z = list(PatternPreset.Z, 4, 4);
		z.anchorSlot = 39; // col 7 -> only one column of room, so the pairs wrap into a single column
		assertTrue(z.fitsGrid());
		assertEquals(39, z.absoluteSlot(0));
		assertEquals(47, z.absoluteSlot(1));
		assertEquals(55, z.absoluteSlot(2));
		assertEquals(63, z.absoluteSlot(3));
		z.anchorSlot = 38; // col 6 -> two columns of room, the classic two-wide Z block
		assertTrue(z.fitsGrid());
		assertEquals(38, z.absoluteSlot(0));
		assertEquals(46, z.absoluteSlot(1));
		assertEquals(39, z.absoluteSlot(2));
		assertEquals(47, z.absoluteSlot(3));
	}

	@Test
	public void presetsGoPastSixAndZWrapsAtTheBankEdge()
	{
		// Vertical: a straight column of all 28, no cap.
		final RegearList v = list(PatternPreset.VERTICAL, 28, 28);
		v.anchorSlot = 0;
		assertEquals(28, v.laneCount());
		assertEquals(27 * 8, v.absoluteSlot(27));
		assertTrue(v.fitsGrid());

		// Z from col 6: two columns of room -> pairs fill 2 wide, then wrap to a new band below.
		final RegearList z = list(PatternPreset.Z, 8, 8);
		z.anchorSlot = 38; // col 6, row 4
		assertEquals(8, z.laneCount());
		final List<PatternOffset> offs = z.effectiveOffsets();
		assertEquals(0, offs.get(4).x); // fifth item starts the wrapped band...
		assertEquals(2, offs.get(4).y); // ...two rows below the anchor
		assertTrue(z.fitsGrid());

		// Z from col 0 with the full 28: uses the whole 8-wide bank, 16 to a band, then wraps.
		final RegearList full = list(PatternPreset.Z, 28, 28);
		full.anchorSlot = 0;
		assertEquals(28, full.laneCount());
		assertTrue(full.fitsGrid());
	}

	@Test
	public void loopWrapsLaneToStart()
	{
		final RegearList l = list(PatternPreset.SINGLE, 1, 4);
		l.advanceLane(0, CompletionBehavior.LOOP); // 2
		l.advanceLane(0, CompletionBehavior.LOOP); // 3
		l.advanceLane(0, CompletionBehavior.LOOP); // 4
		l.advanceLane(0, CompletionBehavior.LOOP); // wraps back to item 1
		assertEquals(1, activeId(l, 0));
	}

	@Test
	public void stopParksLaneAndReportsComplete()
	{
		final RegearList l = list(PatternPreset.SINGLE, 1, 2);
		assertFalse(l.isComplete());
		l.advanceLane(0, CompletionBehavior.STOP); // 2
		l.advanceLane(0, CompletionBehavior.STOP); // past end
		assertTrue(l.isComplete());
	}

	@Test
	public void withdrawnAccumulatesAndResetsOnAdvance()
	{
		final RegearList l = list(PatternPreset.SINGLE, 1, 3);
		l.items.get(0).quantity = 30; // this item requires 30 withdrawn before advancing
		assertEquals(0, l.getWithdrawn(0));
		l.addWithdrawn(0, 10);
		l.addWithdrawn(0, 10);
		assertEquals(20, l.getWithdrawn(0));
		assertEquals(1, activeId(l, 0)); // still on item 1 at 20/30
		l.addWithdrawn(0, 10);
		assertEquals(30, l.getWithdrawn(0));
		l.advanceLane(0, CompletionBehavior.STOP);
		assertEquals(2, activeId(l, 0));
		assertEquals(0, l.getWithdrawn(0)); // resets for the next item
	}

	@Test
	public void alternativesCountAsMatches()
	{
		final RegearItem it = new RegearItem(4587);
		assertFalse(it.matches(4585));
		it.alts.add(4585);
		assertTrue(it.matches(4587)); // the primary id
		assertTrue(it.matches(4585)); // an alternative ("or")
		assertFalse(it.matches(1234));
	}

	@Test
	public void footprintSlotsCoverEveryLane()
	{
		final RegearList l = list(PatternPreset.VERTICAL, 3, 6);
		l.anchorSlot = 39;
		assertEquals(3, l.footprintSlots().size());
		assertTrue(l.footprintSlots().contains(39));
		assertTrue(l.footprintSlots().contains(47));
		assertTrue(l.footprintSlots().contains(55));
	}
}

