package com.anonyser.regear;

import com.google.gson.Gson;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Covers the group data model without a running client: every list gets a stable unique id, groups
 * reference lists by that id, and normalize repairs a loaded blob (backfilling missing ids and
 * dropping group members whose list is gone).
 */
public class RegearGroupTest
{
	private final Gson gson = new Gson();

	@Test
	public void everyListGetsAUniqueNonNullId()
	{
		final RegearList a = new RegearList("a");
		final RegearList b = new RegearList("b");
		assertNotNull(a.id);
		assertNotNull(b.id);
		assertFalse(a.id.isEmpty());
		assertNotEquals(a.id, b.id);
	}

	@Test
	public void normalizeBackfillsAMissingListId()
	{
		final RegearList l = new RegearList("legacy");
		l.id = null; // as a pre-id save would deserialize
		final RegearData data = new RegearData();
		data.lists.add(l);
		data.normalize();
		assertNotNull(l.id);
		assertFalse(l.id.isEmpty());
	}

	@Test
	public void normalizeDropsGroupMembersWhoseListIsGone()
	{
		final RegearList kept = new RegearList("kept");
		final RegearData data = new RegearData();
		data.lists.add(kept);
		final RegearGroup g = new RegearGroup("style");
		g.memberIds = new java.util.ArrayList<>(Arrays.asList(kept.id, "ghost-id"));
		data.groups.add(g);

		data.normalize();

		assertEquals(1, g.memberIds.size());
		assertTrue(g.contains(kept.id));
		assertFalse(g.contains("ghost-id"));
	}

	@Test
	public void normalizeRepairsNullGroupsAndMemberLists()
	{
		final RegearData data = new RegearData();
		data.groups = null; // a pre-groups save
		data.normalize();
		assertNotNull(data.groups);
		assertTrue(data.groups.isEmpty());

		final RegearGroup g = new RegearGroup("x");
		g.memberIds = null;
		data.groups.add(g);
		data.normalize();
		assertNotNull(g.memberIds);
	}

	@Test
	public void groupsSurviveAConfigRoundTrip()
	{
		final RegearData data = new RegearData();
		final RegearList a = new RegearList("main");
		final RegearList b = new RegearList("alt");
		data.lists.add(a);
		data.lists.add(b);
		final RegearGroup g = new RegearGroup("tribrid");
		g.memberIds.add(a.id);
		data.groups.add(g);

		final RegearData back = gson.fromJson(gson.toJson(data), RegearData.class);
		back.normalize();

		assertEquals(1, back.groups.size());
		assertEquals("tribrid", back.groups.get(0).name);
		// The member id still points at the first list after the round trip.
		assertTrue(back.groups.get(0).contains(back.lists.get(0).id));
		assertFalse(back.groups.get(0).contains(back.lists.get(1).id));
	}
}

package com.anonyser.regear;

/**
 * A relative bank-slot offset for one visible lane, measured from a list's anchor slot.
 * {@code x} is columns to the right, {@code y} is rows down. Serialized as part of a custom pattern.
 * Package-private mutable fields keep the JSON compact and let the panel edit offsets in place.
 */
class PatternOffset
{
	int x;
	int y;

	// Required by Gson for deserialization.
	PatternOffset()
	{
	}

	PatternOffset(int x, int y)
	{
		this.x = x;
		this.y = y;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof PatternOffset))
		{
			return false;
		}
		final PatternOffset p = (PatternOffset) o;
		return x == p.x && y == p.y;
	}

	@Override
	public int hashCode()
	{
		return 31 * x + y;
	}

	@Override
	public String toString()
	{
		return "(" + x + "," + y + ")";
	}
}

package com.anonyser.regear;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Global Regear settings. Per-list settings (enabled, visible count, pattern, custom offsets, bank
 * anchor, completion override) live on each {@link RegearList} and are edited from the side panel;
 * the values here are the plugin-wide defaults and toggles.
 */
@ConfigGroup(RegearConfig.GROUP)
public interface RegearConfig extends Config
{
	String GROUP = "regear";

	@ConfigSection(
		name = "Bank display",
		description = "How Regear arranges the active items in the bank",
		position = 0
	)
	String bankSection = "bank";

	@ConfigSection(
		name = "Overlays",
		description = "Item id text and the guidance drawn over the bank",
		position = 1
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Behaviour",
		description = "Rotation, resets and missing-item handling",
		position = 2
	)
	String behaviourSection = "behaviour";

	@ConfigSection(
		name = "Equipment panel",
		description = "A movable panel that mirrors your worn equipment while the bank is open",
		position = 3
	)
	String equipmentSection = "equipment";

	@ConfigItem(
		keyName = "applyInBank",
		name = "Show setups in bank",
		description = "When the bank is open, filter it to the active items of every enabled list<br>"
			+ "and move them into their configured positions. Turn off to keep your lists but<br>"
			+ "leave the bank untouched.",
		position = 0,
		section = bankSection
	)
	default boolean applyInBank()
	{
		return true;
	}

	@Range(min = 1, max = 28)
	@ConfigItem(
		keyName = "defaultVisibleCount",
		name = "Default visible items",
		description = "How many lanes a newly created list starts with (1-28; 28 = a full inventory).",
		position = 1,
		section = bankSection
	)
	default int defaultVisibleCount()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "highlightActive",
		name = "Highlight active slots",
		description = "Draw a coloured box around the bank slots Regear is currently pointing you at.",
		position = 2,
		section = bankSection
	)
	default boolean highlightActive()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		// Fresh key (was activeColor): the meaning changed from "the one highlight" to "the boxes
		// you are NOT on yet", so an old saved colour must not carry over and drown the new scheme.
		keyName = "slotColor",
		name = "Slot boxes",
		description = "Colour of the box around the active item slots you are not on yet.",
		position = 3,
		section = bankSection
	)
	default Color slotColor()
	{
		return new Color(0, 110, 45, 200);
	}

	@Alpha
	@ConfigItem(
		keyName = "currentColor",
		name = "Current click",
		description = "Colour of the box around the slot to click next; it moves through the<br>"
			+ "withdraw order in real time as you take items out.",
		position = 4,
		section = bankSection
	)
	default Color currentColor()
	{
		return new Color(70, 255, 70, 255);
	}

	@ConfigItem(
		keyName = "showLaneNumbers",
		name = "Show lane numbers",
		description = "Number each active slot so the intended click order is obvious.",
		position = 5,
		section = bankSection
	)
	default boolean showLaneNumbers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showNextPreview",
		name = "Show next item",
		description = "Draw a small preview of the item each lane will advance to next.",
		position = 6,
		section = bankSection
	)
	default boolean showNextPreview()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showItemIds",
		name = "Item id overlay",
		description = "Draw each item's id in small white text over items in the bank,<br>"
			+ "inventory and equipment. Handy while building a list.",
		position = 0,
		section = overlaySection
	)
	default boolean showItemIds()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightMissing",
		name = "Mark missing items",
		description = "Draw a marker where an active item should be but is not in the bank.",
