	/** Enable exactly this group's setups and disable every other one — a one-click loadout switch. */
	private void enableGroup()
	{
		final RegearGroup g = selectedGroup();
		if (g == null)
		{
			JOptionPane.showMessageDialog(this, "No group yet. Enable the setups you want, then \"Group checked\".");
			return;
		}
		for (RegearList l : lists())
		{
			l.enabled = g.contains(l.id);
		}
		plugin.commit();
		refreshForSelection();
	}

	/** Turn off this group's setups; anything outside the group keeps its current state. */
	private void disableGroup()
	{
		final RegearGroup g = selectedGroup();
		if (g == null)
		{
			JOptionPane.showMessageDialog(this, "No group selected.");
			return;
		}
		for (RegearList l : lists())
		{
			if (g.contains(l.id))
			{
				l.enabled = false;
			}
		}
		plugin.commit();
		refreshForSelection();
	}

	/** Snapshot the currently-enabled setups into a new named group. */
	private void groupFromChecked()
	{
		final List<String> ids = new ArrayList<>();
		for (RegearList l : lists())
		{
			if (l.enabled)
			{
				ids.add(l.id);
			}
		}
		if (ids.isEmpty())
		{
			JOptionPane.showMessageDialog(this,
				"Tick the setups you want in the dropdown first, then click Group checked.");
			return;
		}
		final String name = JOptionPane.showInputDialog(this, "Group name:", "Group " + (groups().size() + 1));
		if (name == null || name.trim().isEmpty())
		{
			return;
		}
		final Set<String> lower = new HashSet<>();
		for (RegearGroup g : groups())
		{
			if (g.name != null)
			{
				lower.add(g.name.toLowerCase());
			}
		}
		final RegearGroup group = new RegearGroup(RegearShare.uniqueName(name.trim(), lower));
		group.memberIds = ids;
		groups().add(group);
		plugin.commit();
		reloadGroups();
		SwingUtilities.invokeLater(() -> groupSelector.setSelectedIndex(groups().size() - 1));
	}

	/** Overwrite the selected group's members with the setups currently enabled. */
	private void updateGroupFromChecked()
	{
		final RegearGroup g = selectedGroup();
		if (g == null)
		{
			JOptionPane.showMessageDialog(this, "No group selected.");
			return;
		}
		final List<String> ids = new ArrayList<>();
		for (RegearList l : lists())
		{
			if (l.enabled)
			{
				ids.add(l.id);
			}
		}
		if (ids.isEmpty())
		{
			JOptionPane.showMessageDialog(this,
				"Tick the setups you want in the group first, then click Update group.");
			return;
		}
		final int ok = JOptionPane.showConfirmDialog(this,
			"Update group \"" + g.name + "\" to the " + ids.size() + " setup(s) currently enabled?",
			"Update group", JOptionPane.YES_NO_OPTION);
		if (ok != JOptionPane.YES_OPTION)
		{
			return;
		}
		g.memberIds = ids;
		plugin.commit();
		reloadGroups();
	}

	private void renameGroup()
	{
		final RegearGroup g = selectedGroup();
		if (g == null)
		{
			return;
		}
		final String name = JOptionPane.showInputDialog(this, "New group name:", g.name);
		if (name != null && !name.trim().isEmpty())
		{
			g.name = name.trim();
			plugin.commit();
			reloadGroups();
		}
	}

	private void deleteGroup()
	{
		final RegearGroup g = selectedGroup();
		if (g == null)
		{
			return;
		}
		final int ok = JOptionPane.showConfirmDialog(this,
			"Delete group \"" + g.name + "\"? Your setups are not affected.",
			"Delete group", JOptionPane.YES_NO_OPTION);
		if (ok == JOptionPane.YES_OPTION)
		{
			groups().remove(g);
			plugin.commit();
			reloadGroups();
		}
	}

	/**
	 * The setup dropdown, now a checklist. Each row is a checkbox — the list's enabled state — plus
	 * its name: ticking a checkbox enables or disables that setup and keeps the menu open so several
	 * can be set in a row; clicking a name picks that setup for editing and closes the menu. Closed,
	 * the control shows the selected setup's name. Enable all / Disable all and the group buttons all
	 * drive the same enabled flags, so the checkmarks always reflect what is on at the bank.
	 */
	private final class ListSelector extends JPanel
	{
		private final JButton button = new JButton();
		private final JLabel caret = new JLabel("▾");
		private int selectedIndex = -1;
		// When the open menu was last dismissed. A click on the button/caret that closes the menu
		// also re-fires the open handler; this lets us swallow that one so the click toggles it shut.
		private long menuHiddenAt;

		ListSelector()
		{
			super(new BorderLayout(4, 0));
			setAlignmentX(LEFT_ALIGNMENT);
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
			setOpaque(false);
			button.setHorizontalAlignment(SwingConstants.LEFT);
			button.setFocusPainted(false);
			button.setFont(FontManager.getRunescapeFont());
			button.setToolTipText("Pick a setup to edit; tick a checkbox to enable it at the bank");
			button.addActionListener(e -> showMenu());
			caret.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			caret.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
			caret.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					showMenu();
				}
			});
			add(button, BorderLayout.CENTER);
			add(caret, BorderLayout.EAST);
			updateText();
		}

		int getSelectedIndex()
		{
			return selectedIndex;
		}

		void setSelectedIndex(int i)
		{
			final int size = lists().size();
			selectedIndex = size == 0 ? -1 : Math.max(0, Math.min(i, size - 1));
			updateText();
			if (!loading)
			{
				refreshForSelection();
			}
		}

		/** Clamp the selection to the current setups and refresh the label; the editor is refreshed by the caller. */
		void reloadItems()
		{
			final int size = lists().size();
			selectedIndex = size == 0 ? -1 : Math.max(0, Math.min(selectedIndex, size - 1));
			updateText();
		}

		private void updateText()
		{
			final List<RegearList> ls = lists();
			button.setText(selectedIndex >= 0 && selectedIndex < ls.size()
				? ls.get(selectedIndex).name : "(no setups)");
		}

		private void showMenu()
		{
			// A click that dismisses the open menu also lands on the button/caret and would reopen
			// it instantly. Swallow an open that comes right after a close so the click toggles shut.
			if (System.currentTimeMillis() - menuHiddenAt < 200)
			{
				return;
			}
			final JPopupMenu menu = new JPopupMenu();
			menu.addPopupMenuListener(new javax.swing.event.PopupMenuListener()
			{
				@Override
				public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e)
				{
				}

				@Override
				public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e)
				{
					menuHiddenAt = System.currentTimeMillis();
				}

				@Override
				public void popupMenuCanceled(javax.swing.event.PopupMenuEvent e)
				{
					menuHiddenAt = System.currentTimeMillis();
				}
			});
			final List<RegearList> ls = lists();
			if (ls.isEmpty())
			{
				final JMenuItem none = new JMenuItem("No setups yet - use New");
				none.setEnabled(false);
				menu.add(none);
			}
			final int width = Math.max(150, button.getWidth());
			for (int i = 0; i < ls.size(); i++)
			{
				menu.add(menuRow(menu, ls.get(i), i, width));
			}
			menu.show(button, 0, button.getHeight());
		}

		private Component menuRow(JPopupMenu menu, RegearList list, int index, int width)
		{
			final JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 8));
			row.setPreferredSize(new Dimension(width, 24));
			row.setBackground(index == selectedIndex
				? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			final JCheckBox cb = new JCheckBox();
			cb.setSelected(list.enabled);
			cb.setOpaque(false);
			cb.setToolTipText("Enable \"" + list.name + "\" at the bank");
			cb.addActionListener(e ->
			{
				list.enabled = cb.isSelected();
				plugin.commit();
				// Preview footprints and warnings follow the new enabled set; the menu stays open.
				refreshForSelection();
			});
			final JLabel name = new JLabel(list.name);
			name.setForeground(Color.WHITE);
			name.setToolTipText("Edit \"" + list.name + "\"");
			name.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
			name.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					menu.setVisible(false);
					setSelectedIndex(index);
				}
			});
			row.add(cb, BorderLayout.WEST);
			row.add(name, BorderLayout.CENTER);
			return row;
		}
	}

	private void commitAnchor()
	{
		if (loading)
		{
			return;
		}
		final RegearList list = selectedList();
		if (list == null)
		{
			return;
		}
		final Integer col = clamp(parseId(colField.getText()), 0, 7);
		final Integer row = clamp(parseId(rowField.getText()), 0, 40);
		if (col != null && row != null)
		{
			list.anchorSlot = row * RegearList.BANK_COLUMNS + col;
			plugin.commit();
			refreshForSelection();
		}
	}

	private void commitCustomOffsets()
	{
		if (loading)
		{
			return;
		}
		final RegearList list = selectedList();
		if (list == null)
		{
			return;
		}
		list.customOffsets = parseOffsets(customField.getText());
		list.resetLanes();
		plugin.commit();
		refreshForSelection();
	}

	// --- parsing helpers ---------------------------------------------------------------------------

	private static Integer parseId(String text)
	{
		if (text == null)
		{
			return null;
		}
		try
		{
			return Integer.parseInt(text.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Integer clamp(Integer v, int min, int max)
	{
		if (v == null)
		{
			return null;
		}
		return Math.max(min, Math.min(max, v));
	}

	private static List<PatternOffset> parseOffsets(String text)
	{
		final List<PatternOffset> out = new ArrayList<>();
		if (text == null)
		{
			return out;
		}
		for (String token : text.trim().split("\\s+"))
		{
			final String[] parts = token.split(",");
			if (parts.length == 2)
			{
				final Integer x = parseId(parts[0]);
				final Integer y = parseId(parts[1]);
				if (x != null && y != null)
				{
					out.add(new PatternOffset(x, y));
				}
			}
			if (out.size() >= 28)
			{
				break;
			}
		}
		return out;
	}

	private static String offsetsToText(List<PatternOffset> offsets)
	{
		final StringBuilder sb = new StringBuilder();
		for (PatternOffset o : offsets)
		{
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(o.x).append(',').append(o.y);
		}
		return sb.toString();
	}

	private JComponent warning(String text, Color color)
	{
		final JLabel l = new JLabel("<html>" + text + "</html>");
		l.setForeground(color);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setAlignmentX(LEFT_ALIGNMENT);
		l.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		return l;
	}

	/** Item name for a tooltip. Must be called on the client thread (getItemComposition asserts it). */
	private String itemName(int id)
	{
		final ItemComposition c = itemManager.getItemComposition(id);
		return c != null && c.getName() != null ? c.getName() : "Item";
	}

	// --- pattern preview ---------------------------------------------------------------------------

	/**
	 * A to-scale preview of the top of the bank: numbered column and row axes matching the real bank
	 * grid, this list's lanes as numbered green cells at their actual bank positions (anchor +
	 * pattern), the anchor cell outlined orange, and the slots other ENABLED lists occupy in gray so
	 * a new pattern can be placed around them. In "click to set" mode each left click adds (or
	 * removes) a lane at that bank cell, numbered in click order.
	 */
	private final class PatternPreview extends JPanel
	{
		private static final int CELL = 20;
		private static final int AXIS_W = 16;
		private static final int AXIS_H = 13;
		private static final int OX = 2 + AXIS_W;
		private static final int OY = 2 + AXIS_H;
		private static final int MIN_ROWS = 7;
		private static final int MAX_ROWS = 16;
		private RegearList list;

		PatternPreview()
		{
			setAlignmentX(LEFT_ALIGNMENT);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setToolTipText("<html>The bank as Regear sees it: columns 0-7 across the top, rows down the left.<br>"
				+ "Orange outline = this list's anchor (the Col/Row fields). Gray = other enabled lists.</html>");
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (!patternClickMode || list == null || !SwingUtilities.isLeftMouseButton(e))
					{
						return;
					}
					final int col = Math.floorDiv(e.getX() - OX, CELL);
					final int rel = Math.floorDiv(e.getY() - OY, CELL);
					if (col >= 0 && rel >= 0 && col < RegearList.BANK_COLUMNS && rel < displayRows())
					{
						// Clicks land on absolute bank cells; the pattern stores them anchor-relative.
						toggleOffset(col - list.anchorSlot % RegearList.BANK_COLUMNS,
							rowStart() + rel - list.anchorSlot / RegearList.BANK_COLUMNS);
					}
				}
			});
		}

		void setList(RegearList list)
		{
			this.list = list;
			revalidate();
			repaint();
		}

		/**
		 * First bank row shown. Normally 0; when this list is anchored so deep that its pattern
		 * would fall past the row cap, the view windows down to keep the anchor and lanes visible
		 * (the row axis labels stay the real bank row numbers).
		 */
		private int rowStart()
		{
			if (list == null)
			{
				return 0;
			}
			final int anchorRow = list.anchorSlot / RegearList.BANK_COLUMNS;
			int selMin = anchorRow;
			int selMax = anchorRow;
			for (PatternOffset o : list.effectiveOffsets())
			{
				selMin = Math.min(selMin, anchorRow + o.y);
				selMax = Math.max(selMax, anchorRow + o.y);
			}
			if (selMax + 2 <= MAX_ROWS)
			{
				return 0;
			}
			return Math.max(0, selMin - 1);
		}

		/** Rows shown: enough to cover this list's pattern and every other enabled list's, min 7. */
		private int displayRows()
		{
			int maxRow = MIN_ROWS - 2;
			if (list != null)
			{
				final int anchorRow = list.anchorSlot / RegearList.BANK_COLUMNS;
				maxRow = Math.max(maxRow, anchorRow);
				for (PatternOffset o : list.effectiveOffsets())
				{
					maxRow = Math.max(maxRow, anchorRow + o.y);
				}
			}
			for (RegearList other : lists())
			{
				if (other == null || other == list || !other.enabled)
				{
					continue;
				}
				for (int slot : other.footprintSlots())
				{
					maxRow = Math.max(maxRow, slot / RegearList.BANK_COLUMNS);
				}
			}
			return Math.min(MAX_ROWS, Math.max(MIN_ROWS, maxRow + 2 - rowStart()));
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(PANEL_WIDTH - 20, OY + displayRows() * CELL + 2);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, OY + displayRows() * CELL + 2);
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			super.paintComponent(g0);
			if (list == null)
			{
				return;
			}
			final Graphics2D g = (Graphics2D) g0;
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			final int cols = RegearList.BANK_COLUMNS;
			final int rows = displayRows();
			final int start = rowStart();

			// Axis numbers, so the Col/Row anchor fields map straight onto what you see.
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			for (int x = 0; x < cols; x++)
			{
				final String n = String.valueOf(x);
				g.drawString(n, OX + x * CELL + (CELL - g.getFontMetrics().stringWidth(n)) / 2, OY - 3);
			}
			for (int y = 0; y < rows; y++)
			{
				final String n = String.valueOf(start + y);
				g.drawString(n, OX - 4 - g.getFontMetrics().stringWidth(n),
					OY + y * CELL + (CELL + g.getFontMetrics().getAscent()) / 2 - 2);
			}

			// Empty grid squares so the layout reads like the real bank.
			for (int y = 0; y < rows; y++)
			{
				for (int x = 0; x < cols; x++)
				{
					final int cx = OX + x * CELL;
					final int cy = OY + y * CELL;
					g.setColor(ColorScheme.DARK_GRAY_COLOR);
					g.fillRect(cx + 1, cy + 1, CELL - 3, CELL - 3);
					g.setColor(new Color(60, 60, 60));
					g.drawRect(cx, cy, CELL - 1, CELL - 1);
				}
			}

			// Slots other enabled lists occupy, in gray, so this pattern can be placed around them.
			g.setColor(new Color(130, 130, 130, 150));
			for (RegearList other : lists())
			{
				if (other == null || other == list || !other.enabled)
				{
					continue;
				}
				for (int slot : other.footprintSlots())
				{
					final int y = slot / cols - start;
					if (y >= 0 && y < rows)
					{
						g.fillRect(OX + slot % cols * CELL + 1, OY + y * CELL + 1, CELL - 3, CELL - 3);
					}
				}
			}

			// The anchor cell, outlined so the Col/Row fields have a visible target.
			final int anchorCol = list.anchorSlot % cols;
			final int anchorRow = list.anchorSlot / cols;
			if (anchorRow - start >= 0 && anchorRow - start < rows)
			{
				g.setColor(ColorScheme.BRAND_ORANGE);
				g.drawRect(OX + anchorCol * CELL, OY + (anchorRow - start) * CELL, CELL - 1, CELL - 1);
			}

			// Numbered green cells for this list's lanes, at their real bank positions.
			g.setFont(FontManager.getRunescapeBoldFont());
			final List<PatternOffset> offs = list.effectiveOffsets();
			for (int i = 0; i < offs.size(); i++)
			{
				final PatternOffset o = offs.get(i);
				final int x = anchorCol + o.x;
				final int y = anchorRow + o.y - start;
				if (x < 0 || x >= cols || y < 0 || y >= rows)
				{
					continue;
				}
				final int cx = OX + x * CELL;
				final int cy = OY + y * CELL;
				g.setColor(new Color(0, 200, 83, 160));
				g.fillRect(cx + 1, cy + 1, CELL - 3, CELL - 3);
				g.setColor(Color.WHITE);
				final String n = String.valueOf(i + 1);
				g.drawString(n, cx + (CELL - g.getFontMetrics().stringWidth(n)) / 2 + 1, cy + CELL - 5);
			}
		}
	}
}

package com.anonyser.regear;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small movable panel that mirrors the player's worn equipment in the game's own layout (helm on
 * top; cape, amulet, ammo; weapon, body, shield; legs; gloves, boots, ring). It renders only while
 * the bank is open and reads the equipment container each frame, so it updates live as items are
 * equipped. Drag it anywhere like any overlay; it is display-only and never interacts.
 */
class RegearEquipmentOverlay extends Overlay
{
	private static final int SLOT = 36;      // matches the bank/inventory icon width
	private static final int GAP = 4;
	private static final int PAD = 6;
	private static final int COLS = 3;
	private static final int ROWS = 5;
	private static final int WIDTH = PAD * 2 + COLS * SLOT + (COLS - 1) * GAP;
	private static final int HEIGHT = PAD * 2 + ROWS * SLOT + (ROWS - 1) * GAP;

	private final Client client;
	private final RegearConfig config;
	private final ItemManager itemManager;

	@Inject
	RegearEquipmentOverlay(Client client, RegearConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(true);
		setResizable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showEquipmentOverlay() || !bankOpen())
		{
			return null;
		}

		// Panel background so the cells read clearly wherever it is dragged.
		graphics.setColor(new Color(24, 24, 24, 220));
		graphics.fillRect(0, 0, WIDTH, HEIGHT);
		graphics.setColor(new Color(60, 60, 60));
		graphics.drawRect(0, 0, WIDTH - 1, HEIGHT - 1);

		final ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		for (Cell cell : CELLS)
		{
			final int x = PAD + cell.col * (SLOT + GAP);
			final int y = PAD + cell.row * (SLOT + GAP);

			// The equipment cell background, matching the game's empty-slot look.
			graphics.setColor(new Color(40, 40, 40, 235));
			graphics.fillRect(x, y, SLOT, SLOT);
			graphics.setColor(new Color(70, 70, 70));
			graphics.drawRect(x, y, SLOT, SLOT);

			final Item item = equipment == null ? null : equipment.getItem(cell.slot.getSlotIdx());
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			final int qty = Math.max(1, item.getQuantity());
			final BufferedImage img = itemManager.getImage(item.getId(), qty, qty > 1);
			if (img != null)
			{
				// Centre the item sprite in the cell.
				graphics.drawImage(img, x + (SLOT - img.getWidth()) / 2, y + (SLOT - img.getHeight()) / 2, null);
			}
		}
		return new Dimension(WIDTH, HEIGHT);
	}

	private boolean bankOpen()
	{
		final Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return bank != null && !bank.isHidden();
	}

	/** One equipment cell: which worn slot it shows and where it sits in the 3x5 layout. */
	private static final class Cell
	{
		final EquipmentInventorySlot slot;
		final int col;
		final int row;

		Cell(EquipmentInventorySlot slot, int col, int row)
		{
			this.slot = slot;
			this.col = col;
			this.row = row;
		}
	}

	// The classic worn-equipment arrangement.
	private static final Cell[] CELLS = {
		new Cell(EquipmentInventorySlot.HEAD, 1, 0),
		new Cell(EquipmentInventorySlot.CAPE, 0, 1),
		new Cell(EquipmentInventorySlot.AMULET, 1, 1),
		new Cell(EquipmentInventorySlot.AMMO, 2, 1),
		new Cell(EquipmentInventorySlot.WEAPON, 0, 2),
		new Cell(EquipmentInventorySlot.BODY, 1, 2),
		new Cell(EquipmentInventorySlot.SHIELD, 2, 2),
		new Cell(EquipmentInventorySlot.LEGS, 1, 3),
		new Cell(EquipmentInventorySlot.GLOVES, 0, 4),
		new Cell(EquipmentInventorySlot.BOOTS, 1, 4),
		new Cell(EquipmentInventorySlot.RING, 2, 4),
	};
}

package com.anonyser.regear;

import java.util.ArrayList;
import java.util.List;

/**
 * State for the interactive on-bank tutorial. It is client-free: the plugin fills it with example
 * item ids read from whatever bank is open, the overlay draws it, and the plugin's mouse handler
 * advances it. Example items are chosen per session, so it works on any account -- gear items when
 * the bank has at least three equippable items, otherwise it falls back to a plain inventory demo.
 */
class RegearTutorial
{
	static final int ANCHOR_SLOT = 9; // col 1, row 1 -- leaves room for the widest pattern
	static final int FULL_INVENTORY = 28; // slots a full-inventory setup fills (for the rotating demo step)

	static final class Step
	{
		final String title;
		final String instruction;
		final PatternPreset pattern; // null = the closing notes step
		final int count;             // boxes shown per round (the visible window)
		final int total;             // items cleared across all rounds; == count for single-round steps

		Step(String title, String instruction, PatternPreset pattern, int count, int total)
		{
			this.title = title;
			this.instruction = instruction;
			this.pattern = pattern;
			this.count = count;
			this.total = total;
		}
	}

	private final List<Step> steps = new ArrayList<>();
	private List<Integer> items = new ArrayList<>();
	private boolean gearMode;
	private int stepIndex;
	private int clicked; // green boxes clicked so far in the current round
	private int cleared; // items cleared in earlier rounds of the current (rotating) step

	/** Build the step list from the example items. Needs at least 2 items to show anything useful. */
	void start(boolean gearMode, List<Integer> exampleItems)
	{
		this.gearMode = gearMode;
		this.items = new ArrayList<>(exampleItems);
		steps.clear();
		stepIndex = 0;
		clicked = 0;
		cleared = 0;
		final int n = items.size();
		if (n < 2)
		{
			return; // nothing to demonstrate; the overlay shows an "add a few items" note
		}
		final String kind = gearMode ? "Gear setup" : "Inventory setup";
		if (n >= 3)
		{
			final int z = Math.min(4, n);
			steps.add(new Step(kind + " — Z pattern",
				"Click the green boxes 1 to " + z + " in order.", PatternPreset.Z, z, z));
			steps.add(new Step("Single spot",
				"One slot: you click the same spot and it advances to the next item.", PatternPreset.SINGLE, 1, 1));
			final int v = Math.min(3, n);
			steps.add(new Step("Vertical line",
				"A straight column, top to bottom.", PatternPreset.VERTICAL, v, v));
		}
		// Full inventory: a 6-slot window keeps rotating until all 28 inventory slots are filled, exactly
		// like a real full-inventory setup. The example items cycle to stand in for a whole inventory.
		final int fullWindow = Math.min(6, n);
		steps.add(new Step("Full inventory — Z pattern",
			"Click 1 to " + fullWindow + " in order, then keep going until it's full.",
			PatternPreset.Z, fullWindow, FULL_INVENTORY));
		steps.add(new Step("Done!", null, null, 0, 0));
	}

	boolean hasSteps()
	{
		return !steps.isEmpty();
	}

	boolean isFinished()
	{
		return steps.isEmpty() || stepIndex >= steps.size();
	}

	Step current()
	{
		return isFinished() ? null : steps.get(stepIndex);
	}

	int clicked()
	{
		return clicked;
	}

	int stepNumber()
	{
		return stepIndex + 1;
	}

	int stepCount()
	{
		return steps.size();
	}

	/** Progress within a rotating step: items cleared so far, including this round's clicks. */
	int stepProgress()
	{
		return cleared + clicked;
	}

	/** Total items the current step clears; equals the visible window for single-round steps. */
	int stepTotal()
	{
		final Step s = current();
		return s == null ? 0 : s.total;
	}

	/** True when the current step rotates through more items than fit in its visible window. */
	boolean isRotatingStep()
	{
		final Step s = current();
		return s != null && s.pattern != null && s.total > offsets().size();
	}

	boolean isNotesStep()
	{
		final Step s = current();
		return s != null && s.pattern == null;
	}

	List<PatternOffset> offsets()
	{
		final Step s = current();
		if (s == null || s.pattern == null)
		{
			return new ArrayList<>();
		}
		// Tutorial demos use at most 6 items from a roomy anchor, so the full bank width never wraps.
		return s.pattern.offsetsFor(s.count, RegearList.BANK_COLUMNS);
	}

	int boxCount()
	{
		return Math.min(offsets().size(), roundRemaining());
	}

	/** Items still to clear in the current step (its rotation); 0 on the notes step. */
	private int roundRemaining()
	{
		final Step s = current();
		if (s == null || s.pattern == null)
		{
			return 0;
		}
		return s.total - cleared;
	}

	int slotForBox(int k)
	{
		final List<PatternOffset> offs = offsets();
		if (k < 0 || k >= offs.size())
		{
			return -1;
		}
		final PatternOffset o = offs.get(k);
		final int col = ANCHOR_SLOT % RegearList.BANK_COLUMNS + o.x;
		final int row = ANCHOR_SLOT / RegearList.BANK_COLUMNS + o.y;
		return row * RegearList.BANK_COLUMNS + col;
	}

	int itemForBox(int k)
	{
		return items.isEmpty() ? -1 : items.get((cleared + k) % items.size());
	}

	/** The next box the player is expected to click (0-based), or -1 when the round is complete. */
	int expectedBox()
	{
		return clicked < boxCount() ? clicked : -1;
	}

	/** Register a click on box k. In-order clicks advance the round; the notes step finishes on any click. */
	void clickBox(int k)
	{
		final Step s = current();
		if (s == null)
		{
			return;
		}
		if (s.pattern == null)
		{
			stepIndex++; // notes step: any click finishes the tutorial
			return;
		}
		if (k == clicked)
		{
			clicked++;
			final int boxes = boxCount();
			if (clicked >= boxes)
			{
				// Round done: clear this window, then roll to the next window or finish the step.
				cleared += boxes;
				clicked = 0;
				if (cleared >= s.total)
				{
					stepIndex++;
					cleared = 0;
				}
			}
		}
	}

	void reset()
	{
		steps.clear();
		items.clear();
		stepIndex = 0;
		clicked = 0;
		cleared = 0;
	}
}

package com.anonyser.regear;

/**
 * What dropping one item onto another does in the setup editor grid — the same two modes the
 * game's bank offers. Swap trades the two slots; Insert pulls the item out and pushes everything
 * between over by one.
 */
public enum DragMode
{
	SWAP("Swap"),
	INSERT("Insert");

	private final String label;

	DragMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.anonyser.regear;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * One ordered Regear withdrawal sequence and its display settings. The bank shows only a small
 * rotating window of this list at a time: {@code visibleCount} lanes, each showing one item. Lane
 * {@code k} walks the list as {@code k, k+L, k+2L, ...} where {@code L} is the number of lanes, so
 * the lanes together cover the list in order (top-to-bottom, left-to-right in panel order).
 *
 * <p>All rotation and slot math lives here and is deliberately client-free so it can be unit-tested
 * without a running game. The plugin owns detection of a real withdrawal; this class only advances a
 * lane when told to.</p>
 */
class RegearList
{
	static final int BANK_COLUMNS = 8;

	/**
	 * Stable identifier, assigned once and persisted, so a group can reference this list by something
	 * that survives a rename. The field initializer covers both the no-arg (Gson) and named
	 * constructors; a legacy save with no id in its JSON keeps the fresh one assigned here.
	 */
	String id = newId();
	String name;
	boolean enabled;
	List<RegearItem> items = new ArrayList<>();
	int visibleCount = 3;
	PatternPreset pattern = PatternPreset.Z;
	List<PatternOffset> customOffsets = new ArrayList<>();
	/** Base bank slot (0-based, 8-wide grid) that lane offset (0,0) maps to. */
	int anchorSlot = defaultAnchorSlot(0);
	/**
	 * Legacy per-list completion override, kept only so old saved/shared setups still deserialize.
	 * The plugin no longer reads it: the completion behaviour in the plugin options applies to
	 * every list.
	 */
	CompletionBehavior completion;
	/** Persisted progress: {@code laneCursors[k]} is the item index currently shown in lane k. */
	int[] laneCursors;
	/**
	 * Runtime-only (not persisted): the game tick at which each lane's post-withdrawal hold ends. A
	 * lane is held (its slot shown empty) while the current tick is below this value, so mashing a
	 * slot pulls only one item per hold window. Set on advance; expires by tick.
	 */
	transient int[] laneHoldUntilTick;
	/**
	 * Runtime-only (not persisted): how much of the current active item each lane has seen withdrawn
	 * so far. A lane only advances once this reaches the item's required quantity, so an item stays
	 * put while you withdraw it in chunks (e.g. Withdraw-10 three times for 30 runes).
	 */
	transient int[] laneWithdrawn;

	// Required by Gson for deserialization.
	RegearList()
	{
	}

	RegearList(String name)
	{
		this.name = name;
	}

	/** A fresh, unique list id. */
	static String newId()
	{
		return java.util.UUID.randomUUID().toString();
	}

	/**
	 * The default anchor slot for the Nth enabled list: first sits at column 6 ~4 rows down (leaving
	 * room for the two-column default Z pattern to reach column 7), each later list steps two columns
	 * left so patterns up to two columns wide do not collide.
	 */
	static int defaultAnchorSlot(int order)
	{
		final int col = Math.max(0, 6 - order * 2);
		final int row = 4;
		return row * BANK_COLUMNS + col;
	}

	/** Repairs nulls and clamps ranges after a config load, where Gson may have left gaps. */
	void normalize()
	{
		if (id == null || id.isEmpty())
		{
			id = newId();
		}
		if (items == null)
		{
			items = new ArrayList<>();
		}
		for (RegearItem item : items)
		{
			if (item != null && item.alts == null)
			{
				item.alts = new ArrayList<>();
			}
		}
		if (customOffsets == null)
		{
			customOffsets = new ArrayList<>();
		}
		if (pattern == null)
		{
			pattern = PatternPreset.Z;
		}
		visibleCount = Math.max(1, Math.min(28, visibleCount));
		ensureLanes();
	}

	/** The lane offsets actually in effect: a preset derives them from the count, CUSTOM stores them. */
	List<PatternOffset> effectiveOffsets()
	{
		if (pattern == PatternPreset.CUSTOM)
		{
			if (customOffsets.isEmpty())
			{
				// Nothing configured yet: fall back to a single spot so the list still shows something.
				final List<PatternOffset> one = new ArrayList<>();
				one.add(new PatternOffset(0, 0));
				return one;
			}
			return customOffsets.size() > 28 ? customOffsets.subList(0, 28) : customOffsets;
		}
		// Presets wrap at the bank's right edge, so the width they can use depends on the anchor.
		return pattern.offsetsFor(visibleCount, BANK_COLUMNS - anchorSlot % BANK_COLUMNS);
	}

	/** Number of visible lanes, i.e. the rotation step. */
	int laneCount()
	{
		return effectiveOffsets().size();
	}

	/** (Re)initialise lane cursors if missing or the lane count changed; each lane starts at its index. */
	void ensureLanes()
	{
		final int lanes = laneCount();
		if (laneCursors == null || laneCursors.length != lanes)
		{
			resetLanes();
		}
	}

	/** Restart the whole sequence: lane k shows item k again. */
	void resetLanes()
	{
		final int lanes = laneCount();
		laneCursors = new int[lanes];
		for (int k = 0; k < lanes; k++)
		{
			laneCursors[k] = k;
		}
		laneHoldUntilTick = null;
		laneWithdrawn = null;
	}

	/** Hold a lane empty until the given game tick (anti-spam limiter). */
	void holdLane(int lane, int releaseTick)
	{
		final int lanes = laneCount();
		if (laneHoldUntilTick == null || laneHoldUntilTick.length != lanes)
		{
			laneHoldUntilTick = new int[lanes];
		}
		if (lane >= 0 && lane < laneHoldUntilTick.length)
		{
			laneHoldUntilTick[lane] = releaseTick;
		}
	}

	boolean isLaneHeld(int lane, int currentTick)
	{
		return laneHoldUntilTick != null && lane >= 0 && lane < laneHoldUntilTick.length
			&& currentTick < laneHoldUntilTick[lane];
	}

	/** True if any lane's hold ends exactly on this tick (so the next item should now be shown). */
	boolean releaseDue(int currentTick)
	{
		if (laneHoldUntilTick == null)
		{
			return false;
		}
		for (int until : laneHoldUntilTick)
		{
			if (until == currentTick)
			{
				return true;
			}
		}
		return false;
	}

	void clearHolds()
	{
		laneHoldUntilTick = null;
	}

	/** Add to the amount withdrawn of a lane's current item. */
	void addWithdrawn(int lane, int amount)
	{
		final int lanes = laneCount();
		if (laneWithdrawn == null || laneWithdrawn.length != lanes)
		{
			laneWithdrawn = new int[lanes];
		}
		if (lane >= 0 && lane < laneWithdrawn.length)
		{
			laneWithdrawn[lane] += amount;
		}
	}

	int getWithdrawn(int lane)
	{
		return laneWithdrawn != null && lane >= 0 && lane < laneWithdrawn.length ? laneWithdrawn[lane] : 0;
	}

	void setWithdrawn(int lane, int amount)
	{
		final int lanes = laneCount();
		if (laneWithdrawn == null || laneWithdrawn.length != lanes)
		{
			laneWithdrawn = new int[lanes];
		}
		if (lane >= 0 && lane < laneWithdrawn.length)
		{
			laneWithdrawn[lane] = amount;
		}
	}

	void clearWithdrawn()
	{
		laneWithdrawn = null;
	}

	/** Absolute bank slot for a lane = anchor + offset, or -1 if it would fall outside the grid. */
	int absoluteSlot(int lane)
	{
		final List<PatternOffset> offs = effectiveOffsets();
		if (lane < 0 || lane >= offs.size())
		{
			return -1;
		}
		final PatternOffset o = offs.get(lane);
		final int col = anchorSlot % BANK_COLUMNS + o.x;
		final int row = anchorSlot / BANK_COLUMNS + o.y;
		if (col < 0 || col >= BANK_COLUMNS || row < 0)
		{
			return -1;
		}
		return row * BANK_COLUMNS + col;
	}

	/** The item index currently shown in a lane (may be past the end of the list). */
	int activeIndex(int lane)
	{
		ensureLanes();
		if (lane < 0 || lane >= laneCursors.length)
		{
			return -1;
		}
		return laneCursors[lane];
	}

	/** The item currently shown in a lane, or null if that lane has run past the end of the list. */
	RegearItem activeItem(int lane)
	{
		final int idx = activeIndex(lane);
		if (idx < 0 || idx >= items.size())
		{
			return null;
		}
		return items.get(idx);
	}

	/** The item a lane will show after its current one, for the optional "next" preview; may be null. */
	RegearItem nextItem(int lane)
	{
		final int idx = activeIndex(lane);
		final int next = idx + laneCount();
		if (idx < 0 || next >= items.size())
		{
			return null;
		}
		return items.get(next);
	}

	/**
	 * Advance one lane to its next item, applying the completion behaviour when it runs off the end.
	 * LOOP restarts just that lane at its base index; every other behaviour parks the lane past the
	 * end (so it shows nothing) and lets the plugin handle any whole-sequence reset out of band.
	 */
	void advanceLane(int lane, CompletionBehavior effective)
	{
		ensureLanes();
		if (lane < 0 || lane >= laneCursors.length)
		{
			return;
		}
		final int step = laneCount();
		int next = laneCursors[lane] + step;
		if (next >= items.size())
		{
			if (effective == CompletionBehavior.LOOP)
			{
				next = lane;
			}
			else
			{
				next = items.size();
			}
		}
		laneCursors[lane] = next;
		if (laneWithdrawn != null && lane < laneWithdrawn.length)
		{
			laneWithdrawn[lane] = 0;
		}
	}

	/** True once every lane has run past the end of the list. */
	boolean isComplete()
	{
		ensureLanes();
		for (int k = 0; k < laneCursors.length; k++)
		{
			if (laneCursors[k] < items.size())
			{
				return false;
			}
		}
		return true;
	}

	/** All bank slots this list's pattern occupies (its footprint), for cross-list overlap checks. */
	Set<Integer> footprintSlots()
	{
		final Set<Integer> slots = new LinkedHashSet<>();
		final int lanes = laneCount();
		for (int k = 0; k < lanes; k++)
		{
			final int slot = absoluteSlot(k);
			if (slot >= 0)
			{
				slots.add(slot);
			}
		}
		return slots;
	}

	/** True if the pattern stays within the 8-column grid from the current anchor (no row wrap). */
	boolean fitsGrid()
	{
		for (int k = 0; k < laneCount(); k++)
		{
			if (absoluteSlot(k) < 0)
			{
				return false;
			}
		}
		return true;
	}
}

package com.anonyser.regear;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

/**
 * The bank layout engine. When the bank is open, this resolves the active target of each enabled list
 * into a fixed bank slot and drives RuneLite's core Bank Tags layout system to show only those items,
 * each in its configured position, so the same few bank slots can be clicked in rhythm.
 *
 * <p>Rather than repositioning bank widgets itself, Regear feeds core: it registers a live filter
 * predicate (a {@link net.runelite.client.plugins.banktags.BankTag}) for a private hidden tag, builds a
 * {@link Layout} mapping each active item to its slot, hands it to core's {@link LayoutManager} with
 * {@link LayoutManager#saveLayout(Layout)}, and opens the tag via
 * {@link BankTagsPlugin#openTag(String, Layout, int)} so core filters and lays the bank out live. It is
 * display-only: it never clicks or withdraws; the player does every click.</p>
 */
@Singleton
class RegearBankController
{
	// Bank grid geometry, matching RuneLite core (BankTagsPlugin): 8 columns of 36x32 icons. Still used
	// by the overlays and tutorial to draw at the slots core positions items in.
	static final int COLUMNS = 8;
	static final int ITEM_WIDTH = 36;
	static final int ITEM_HEIGHT = 32;
	static final int X_PADDING = 12;
	static final int Y_PADDING = 4;
	static final int START_X = 51;
	static final int START_Y = 0;

	// A private, hidden bank-tag name Regear drives. Chosen to be unlikely to collide with a real user
	// tag; it never appears in the tag bar (setHidden) and is filtered by a registered predicate, so no
	// per-item tags are ever written to the user's config.
	private static final String REGEAR_TAG = "regearguide";

	/** One positioned (or missing) active item, recorded for the overlay to annotate. */
	static final class Placement
	{
		final String listName;
		RegearList list;     // the list this placement belongs to
		final int lane;      // 0-based lane index within its list
		final int slot;      // absolute bank slot
		final RegearItem item;
		RegearItem next;     // what this lane advances to next, for the preview; may be null
		boolean missing;     // the active item (and any "or" alternative) is not in the bank
		int withdrawn;       // amount of this item withdrawn so far toward its required quantity
		int required;        // quantity to withdraw before the lane advances (>=1)
		int shownId;         // the canonical id actually shown/withdrawn (primary, or an "or" alternative)
		int itemIndex;       // position of the active item within its list (the withdraw order)
		boolean current;     // this is the slot its list wants clicked next (earliest pending item)

		Placement(String listName, int lane, int slot, RegearItem item)
		{
			this.listName = listName;
			this.lane = lane;
			this.slot = slot;
			this.item = item;
		}
	}

	private final Client client;
	private final RegearConfig config;
	private final ItemManager itemManager;
	private final BankTagsPlugin bankTags;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;
	private final BankSearch bankSearch;

	private RegearData data;
	private final List<Placement> placements = new ArrayList<>();
	private final List<String> missingLabels = new ArrayList<>();
	private boolean overlapDetected;
	private boolean tutorialActive;
	private final RegearTutorial tutorial = new RegearTutorial();

	// The set of (canonical) item ids the bank should currently show. The registered filter predicate
	// reads this live, so advancing the window is just a matter of updating this set and re-opening.
	private final Set<Integer> windowIds = new HashSet<>();
	private boolean tagRegistered;

	// When suppressed (the panel's Hide overlay button, or the tab-away auto-hide), the guide releases
	// the bank and draws nothing until shown again. Owned by the plugin; refreshed before each apply.
	private boolean guideSuppressed;
	// True while our tag is the one we last opened. Lets the plugin notice the player navigating to a
	// different bank tab (our tag is no longer active) and auto-hide the guide.
	private boolean lastApplied;

	@Inject
	RegearBankController(Client client, RegearConfig config, ItemManager itemManager,
		BankTagsPlugin bankTags, TagManager tagManager, LayoutManager layoutManager, BankSearch bankSearch)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
		this.bankTags = bankTags;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
		this.bankSearch = bankSearch;
	}

	void setData(RegearData data)
	{
		this.data = data;
	}

	List<Placement> getPlacements()
	{
		return placements;
	}

	List<String> getMissingLabels()
	{
		return missingLabels;
	}

	boolean isOverlapDetected()
	{
		return overlapDetected;
	}

	boolean isTutorialActive()
	{
		return tutorialActive;
	}

	void setTutorialActive(boolean active)
	{
		this.tutorialActive = active;
	}

	RegearTutorial getTutorial()
	{
		return tutorial;
	}

	void setGuideSuppressed(boolean suppressed)
	{
		this.guideSuppressed = suppressed;
	}

	boolean isGuideSuppressed()
	{
		return guideSuppressed;
	}

	/**
	 * True if the guide was showing but our tag is no longer the active one -- i.e. the player clicked
	 * a different bank tab. Used to auto-hide the guide so it stops fighting the tab they chose.
	 */
	boolean userLeftOurTag()
	{
		return lastApplied && !REGEAR_TAG.equals(bankTags.getActiveTag());
	}

	static int slotToX(int slot)
	{
		return slot % COLUMNS * (ITEM_WIDTH + X_PADDING) + START_X;
	}

	static int slotToY(int slot)
	{
		return slot / COLUMNS * (ITEM_HEIGHT + Y_PADDING) + START_Y;
	}

	/**
	 * Recompute the active targets and drive core to filter + lay the bank out. Runs on the client
	 * thread. Registers the hidden Regear tag on first use. When nothing should be managed (disabled,
	 * tutorial running, or no enabled list has an active target) it releases the tag so the bank returns
	 * to normal.
	 *
	 * @param currentTick current game tick, used to evaluate each lane's anti-spam hold
	 */
	void applyLayout(int currentTick)
	{
		placements.clear();
		missingLabels.clear();
		overlapDetected = false;

		if (data == null || !config.applyInBank() || tutorialActive || guideSuppressed)
		{
			release();
			return;
		}

		final ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return;
		}

		// Canonical ids of the REAL items in the bank, for the "or"-alternative pick and the missing
		// check. A bank placeholder (the greyed slot with a "Release" option) must NOT count as present,
		// or the guide keeps showing the primary and never falls back to an "or" alternative (the
		// placeholder bug). A placeholder is either the item id at quantity 0, or a distinct placeholder
		// item id that canonicalizes back to the real item; skip both.
		final Set<Integer> bankIds = new HashSet<>();
		for (Item it : bank.getItems())
		{
			final int id = it.getId();
			if (id < 0 || it.getQuantity() <= 0)
			{
				continue;
			}
			final ItemComposition comp = itemManager.getItemComposition(id);
			if (comp != null && comp.getPlaceholderTemplateId() != -1)
			{
				continue; // a bank placeholder, not a real item
			}
			bankIds.add(itemManager.canonicalize(id));
		}

		// Resolve the active target of every enabled list into a slot, tracking cross-list overlap. A
		// held lane (just withdrawn) still keeps the bank filtered but leaves its slot empty.
		final Map<Integer, Placement> bySlot = new LinkedHashMap<>();
		boolean managing = false;
		for (RegearList list : data.lists)
		{
			if (list == null || !list.enabled)
			{
				continue;
			}
			list.ensureLanes();
			final int lanes = list.laneCount();
			for (int lane = 0; lane < lanes; lane++)
			{
				final RegearItem item = list.activeItem(lane);
				final int slot = list.absoluteSlot(lane);
				if (item == null || slot < 0 || item.alwaysSkipped())
				{
					continue;
				}
				managing = true;
				if (list.isLaneHeld(lane, currentTick))
				{
					continue;
				}
				final Placement p = new Placement(list.name, lane, slot, item);
				p.list = list;
				p.next = list.nextItem(lane);
				p.withdrawn = list.getWithdrawn(lane);
				p.required = Math.max(1, item.quantity);
				p.itemIndex = list.activeIndex(lane);
				if (bySlot.containsKey(slot))
				{
					overlapDetected = true;
					continue;
				}
				bySlot.put(slot, p);
			}
		}

		if (!managing)
		{
			// No enabled list has anything to manage: hand the bank back to the game.
			release();
			return;
		}

		// Build the filter set + the layout from the resolved placements.
		final Layout layout = new Layout(REGEAR_TAG);
		final Set<Integer> newWindow = new HashSet<>();
		for (Placement p : bySlot.values())
		{
			// Show whichever of the item's ids (primary, then "or" alternatives) is actually in the bank.
			int shownId = -1;
			final int primary = itemManager.canonicalize(p.item.id);
			if (bankIds.contains(primary))
			{
				shownId = primary;
			}
			else if (p.item.alts != null)
			{
				for (int alt : p.item.alts)
				{
					final int c = itemManager.canonicalize(alt);
					if (bankIds.contains(c))
					{
						shownId = c;
						break;
					}
				}
			}
			if (shownId < 0)
			{
				p.missing = true;
				p.shownId = primary;
				missingLabels.add(missingLabel(p));
				placements.add(p);
				continue;
			}
			p.shownId = shownId;
			layout.setItemAtPos(shownId, p.slot);
			newWindow.add(shownId);
			placements.add(p);
		}

		// Mark, per list, the slot the player should click NOW: the earliest pending item (lowest
		// list index) among its visible, present slots. The overlay draws it in the "current click"
		// colour, and it moves through the order in real time as lanes advance.
		final Map<RegearList, Placement> currentByList = new LinkedHashMap<>();
		for (Placement p : placements)
		{
			if (p.missing)
			{
				continue;
			}
			final Placement best = currentByList.get(p.list);
			if (best == null || p.itemIndex < best.itemIndex)
			{
				currentByList.put(p.list, p);
			}
		}
		for (Placement p : currentByList.values())
		{
			p.current = true;
		}

		// Update the live filter set, then drive core to filter + lay out the bank. openTag relayouts
		// immediately, so the window advances live as items are withdrawn.
		windowIds.clear();
		windowIds.addAll(newWindow);
		ensureTagRegistered();
		// Store the layout on the tag through core's LayoutManager, then open it. openTag applies the same
		// layout immediately (relayout) so the window advances live as items are withdrawn.
		layoutManager.saveLayout(layout);
		bankTags.openTag(REGEAR_TAG, layout, BankTagsService.OPTION_HIDE_TAG_NAME);
		lastApplied = true;
	}

	/** Register the hidden filter predicate once. The predicate reads {@link #windowIds} live. */
	private void ensureTagRegistered()
	{
		if (!tagRegistered)
		{
			tagManager.registerTag(REGEAR_TAG, id -> windowIds.contains(itemManager.canonicalize(id)));
			tagManager.setHidden(REGEAR_TAG, true);
			tagRegistered = true;
		}
	}

	/**
	 * Force the bank widget to rebuild so a layout change shows at once. Panel and config edits
	 * need this: openTag with our tag already active does not rebuild the view by itself, so
	 * without a bank/inventory change the new window would not appear until the next natural
	 * rebuild (a withdrawal, a tab click, or reopening the bank). The same call core's own tag
	 * tabs use. Client thread only.
	 */
	void forceRebuild()
	{
		if (!lastApplied)
		{
			return;
		}
		final Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bank != null && !bank.isHidden())
		{
			bankSearch.layoutBank();
		}
	}

	/** Close our tag if it is the one currently open, returning the bank to its normal view. */
	private void release()
	{
		lastApplied = false;
		if (REGEAR_TAG.equals(bankTags.getActiveTag()))
		{
			bankTags.closeBankTag();
		}
	}

	/** Release the bank and drop the registered tag. Called on shutdown, on the client thread. */
	void unregister()
	{
		release();
		if (tagRegistered)
		{
			tagManager.unregisterTag(REGEAR_TAG);
			layoutManager.removeLayout(REGEAR_TAG);
			tagRegistered = false;
		}
		windowIds.clear();
		placements.clear();
		missingLabels.clear();
	}

	private static String missingLabel(Placement p)
	{
		final String id = "id " + p.item.id;
		final String note = p.item.note != null && !p.item.note.isEmpty() ? p.item.note + " (" + id + ")" : id;
		return p.listName + ": " + note;
	}
}

package com.anonyser.regear;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Draws each item's id in small white text over items in the bank, inventory and worn equipment,
 * so ids are easy to read while building a Regear list. Gated by a single config toggle.
 */
class RegearIdOverlay extends WidgetItemOverlay
{
	private final RegearConfig config;

	@Inject
	RegearIdOverlay(RegearConfig config)
	{
		this.config = config;
		showOnInventory();
		showOnBank();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showItemIds())
		{
			return;
		}
		final Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}
		final String text = Integer.toString(itemId);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics fm = graphics.getFontMetrics();
		final int tw = fm.stringWidth(text);
		final int x = bounds.x + (bounds.width - tw) / 2;
		final int y = bounds.y + (bounds.height + fm.getAscent()) / 2 - 1;
		// Dead centre of the icon, on a filled backing strip: the game's quantity owns the top-left
		// corner and charge counters / Regear's own withdraw progress own the bottom-left, so the
		// middle is the one spot where the id stays readable without piling onto other text.
		graphics.setColor(new Color(0, 0, 0, 180));
		graphics.fillRect(x - 2, y - fm.getAscent(), tw + 4, fm.getAscent() + 3);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, x, y);
	}
}

package com.anonyser.regear;

import java.util.ArrayList;
import java.util.List;

/**
 * One entry in a Regear list: an item id, an optional quantity, an optional note, and optional
 * "or" alternatives -- other item ids that satisfy the same slot (e.g. a fresh vs a used/degraded
 * variant). Any of them counts as this item for matching a withdrawal, and the bank shows whichever
 * one you actually own. Duplicates of the same id across a list are allowed and expected, so equality
 * is identity-based, not value-based.
 */
class RegearItem
{
	int id;
	/** How many of this item to withdraw before the lane advances (0/1 = advance after one). */
	int quantity;
	/** Optional short label shown under the slot; may be null. */
	String note;
	/** Alternative item ids that also satisfy this slot ("or"); any of them counts as a match. */
	List<Integer> alts = new ArrayList<>();
	/** If set, this item counts as already satisfied while you are wearing it, so it is not shown in
	 *  the regear (e.g. a Ring of Recoil you still have on -- no point pulling another). Per list. */
	boolean skipIfWorn;
	/** Manually omitted from this list: kept as a placeholder but skipped in the regear, unconditionally. */
	boolean omitted;
	/** A deliberate empty inventory slot: no item, never withdrawn, occupying a position in the list. */
	boolean blank;

	// Required by Gson for deserialization.
	RegearItem()
	{
	}

	RegearItem(int id)
	{
		this.id = id;
	}

	RegearItem(int id, int quantity, String note)
	{
		this.id = id;
		this.quantity = quantity;
		this.note = note;
	}

	/** True if the given item id is this item or one of its alternatives. */
	boolean matches(int otherId)
	{
		return otherId == id || (alts != null && alts.contains(otherId));
	}

	/**
	 * True if this entry is never withdrawn no matter what you own or wear -- a blank slot or a
	 * manually omitted item. It stays in the list as a placeholder, but the cycle steps past it.
	 */
	boolean alwaysSkipped()
	{
		return blank || omitted;
	}

	RegearItem copy()
	{
		final RegearItem c = new RegearItem(id, quantity, note);
		if (alts != null)
		{
			c.alts = new ArrayList<>(alts);
		}
		c.skipIfWorn = skipIfWorn;
		c.omitted = omitted;
		c.blank = blank;
		return c;
	}
}

package com.anonyser.regear;

import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Set;

/**
 * Serialises Regear setups to and from a single line of shareable text, so a whole set (or one list)
 * can be copied to the clipboard and pasted by someone else to mirror it exactly. The text is a short
 * prefix plus Base64 of the setups' JSON, which survives being pasted through chat apps on one line.
 * Kept deliberately client-free so it can be unit-tested without a running game.
 */
final class RegearShare
{
	/** Marks Regear share text and carries a format version for future migrations. */
	static final String PREFIX = "regear1:";

	private RegearShare()
	{
	}

	/**
	 * Encode the given lists into one shareable token. Sequence progress is dropped so the imported
	 * copy always starts fresh; everything the recipient needs to mirror the setup is kept.
	 */
	static String export(List<RegearList> lists, Gson gson)
	{
		final RegearData out = new RegearData();
		if (lists != null)
		{
			for (RegearList list : lists)
			{
				if (list == null)
				{
					continue;
				}
				// Deep-copy via a JSON round-trip, then drop the persisted sequence progress.
				final RegearList copy = gson.fromJson(gson.toJson(list), RegearList.class);
				copy.laneCursors = null;
				out.lists.add(copy);
			}
		}
		final String json = gson.toJson(out);
		return PREFIX + Base64.getEncoder().encodeToString(json.getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Decode share text back into setups, tolerant of surrounding whitespace, a missing prefix, or
	 * raw (un-encoded) JSON. Each returned list is normalised and reset to its start. Returns an empty
	 * list if nothing valid could be read.
	 */
	static List<RegearList> parse(String text, Gson gson)
	{
		final List<RegearList> result = new ArrayList<>();
		if (text == null)
		{
			return result;
		}
		String body = text.trim();
		if (body.isEmpty())
		{
			return result;
		}
		if (body.startsWith(PREFIX))
		{
			body = body.substring(PREFIX.length()).trim();
		}
		String json;
		try
		{
			json = new String(Base64.getDecoder().decode(body), StandardCharsets.UTF_8);
		}
		catch (IllegalArgumentException notBase64)
		{
			// Someone may have pasted raw JSON: fall back to using the text as-is.
			json = body;
		}
		final RegearData data;
		try
		{
			data = gson.fromJson(json, RegearData.class);
		}
		catch (Exception badJson)
		{
			return result;
		}
		if (data == null || data.lists == null)
		{
			return result;
		}
		data.normalize();
		for (RegearList list : data.lists)
		{
			if (list != null && list.name != null && !list.name.trim().isEmpty())
			{
				list.resetLanes();
				result.add(list);
			}
		}
		return result;
	}

	/**
	 * A name based on {@code base} that is not already taken (case-insensitive): returns {@code base}
	 * unchanged if free, otherwise appends " (2)", " (3)", ... The provided set is not modified.
	 */
	static String uniqueName(String base, Set<String> existingLower)
	{
		final String name = base == null || base.trim().isEmpty() ? "Regear" : base.trim();
		if (existingLower == null || !existingLower.contains(name.toLowerCase()))
		{
			return name;
		}
		for (int n = 2; n < 10000; n++)
		{
			final String candidate = name + " (" + n + ")";
			if (!existingLower.contains(candidate.toLowerCase()))
			{
				return candidate;
			}
		}
		return name;
	}
}

package com.anonyser.regear;

import java.util.ArrayList;
import java.util.List;

/**
 * A named batch of setups you can turn on or off in one action. Members are stored by each list's
 * stable {@link RegearList#id} rather than by name, so renaming a setup keeps it in its groups and
 * deleting one cleanly drops it. A setup may belong to more than one group.
 *
 * <p>Enabling a group is an exclusive switch: its member lists become the only enabled ones.
 * Disabling a group just turns its members off and leaves everything else as it was.</p>
 */
class RegearGroup
{
	String name;
	List<String> memberIds = new ArrayList<>();

	// Required by Gson for deserialization.
	RegearGroup()
	{
	}

	RegearGroup(String name)
	{
		this.name = name;
	}

	boolean contains(String listId)
	{
		return listId != null && memberIds.contains(listId);
	}
}

package com.anonyser.regear;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Annotates the bank on top of the repositioned items: a highlight box and lane number on each
 * active slot, an optional preview of the next item, and a marker where an active item is missing
 * from the bank. Reads the placements the {@link RegearBankController} recorded on the last rebuild.
 * Purely informational; it draws, it never interacts.
 */
class RegearBankOverlay extends Overlay
{
	private final Client client;
	private final RegearConfig config;
	private final ItemManager itemManager;
	private final RegearBankController controller;

	@Inject
	RegearBankOverlay(Client client, RegearConfig config, ItemManager itemManager,
		RegearBankController controller)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
		this.controller = controller;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (controller.isTutorialActive())
		{
			final Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
			if (bank == null || bank.isHidden())
			{
				drawOpenBankMessage(graphics);
			}
			else
			{
				drawTutorial(graphics, bank);
			}
			return null;
		}
		if (!config.applyInBank() || controller.isGuideSuppressed())
		{
			return null;
		}
		final Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return null;
		}
		final Rectangle view = container.getBounds();
		if (view == null)
		{
			return null;
		}
		// The bank scrolls: offset each slot by the current scroll so the highlights track the items,
		// and only draw a box whose cell is fully within the visible area, so it disappears when the
		// item is scrolled out of view and pops back onto it when scrolled back.
		final int scrollY = container.getScrollY();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		for (RegearBankController.Placement p : controller.getPlacements())
		{
			final Rectangle b = slotRect(view, scrollY, p.slot);
			if (b == null)
			{
				continue; // this slot is scrolled out of the visible bank area
			}
			if (p.missing)
			{
				if (config.highlightMissing())
				{
					drawMissing(graphics, b);
				}
				continue;
			}
			if (config.highlightActive())
			{
				// Thin boxes so the items stay visible; the slot to click next stands out in the
				// "current click" colour and walks the withdraw order live.
				graphics.setColor(p.current ? config.currentColor() : config.slotColor());
				graphics.setStroke(new BasicStroke(1f));
				graphics.drawRect(b.x, b.y, b.width, b.height);
			}
			if (config.showLaneNumbers())
			{
				drawLaneNumber(graphics, b, p.lane + 1);
			}
			if (config.showNextPreview() && p.next != null)
			{
				drawNextPreview(graphics, b, p.next.id);
			}
			if (p.required > 1)
			{
				drawProgress(graphics, b, p.withdrawn, p.required);
			}
		}
		return null;
	}

	private void drawOpenBankMessage(Graphics2D g)
	{
		final String msg = "Open the bank to start the Regear tutorial";
		g.setFont(FontManager.getRunescapeBoldFont());
		final int w = g.getFontMetrics().stringWidth(msg) + 24;
		final int h = 34;
		final int x = Math.max(4, (client.getCanvasWidth() - w) / 2);
		final int y = 70;
		final boolean on = System.currentTimeMillis() / 450 % 2 == 0;
		g.setColor(new Color(0, 0, 0, 205));
		g.fillRoundRect(x, y, w, h, 8, 8);
		g.setStroke(new BasicStroke(3f));
		g.setColor(on ? new Color(0, 220, 60) : new Color(230, 210, 0));
		g.drawRoundRect(x, y, w, h, 8, 8);
		g.setColor(Color.WHITE);
		g.drawString(msg, x + 12, y + 22);
	}

	private void drawTutorial(Graphics2D g, Widget container)
	{
		final Rectangle cb = container.getBounds();
		final Point loc = container.getCanvasLocation();
		if (cb == null || loc == null)
		{
			return;
		}
		final RegearTutorial t = controller.getTutorial();

		// Dim the whole bank red so the green targets stand out.
		g.setColor(new Color(150, 20, 20, 90));
		g.fillRect(cb.x, cb.y, cb.width, cb.height);

		if (!t.hasSteps())
		{
			drawStepBanner(g, cb, "Add a few items to your bank",
				"The tutorial needs at least two items to demonstrate.", null);
			return;
		}
		if (t.isNotesStep())
		{
			drawNotes(g, cb);
			return;
		}
		final RegearTutorial.Step step = t.current();
		if (step == null)
		{
			return;
		}
		final String progress = t.isRotatingStep() ? t.stepProgress() + " / " + t.stepTotal() : null;
		drawStepBanner(g, cb, "(" + t.stepNumber() + "/" + t.stepCount() + ")  " + step.title, step.instruction, progress);

		final boolean pulse = System.currentTimeMillis() / 350 % 2 == 0;
		final int expected = t.expectedBox();
		for (int k = 0; k < t.boxCount(); k++)
		{
			final int slot = t.slotForBox(k);
			if (slot < 0)
			{
				continue;
			}
			final int x = loc.getX() + RegearBankController.slotToX(slot);
			final int y = loc.getY() + RegearBankController.slotToY(slot);
			final boolean done = k < t.clicked();
			final boolean next = k == expected;
			g.setColor(new Color(0, 0, 0, 215));
			g.fillRect(x - 1, y - 1, 38, 34);
			final BufferedImage img = itemManager.getImage(t.itemForBox(k));
			if (img != null)
			{
				g.drawImage(img, x, y, null);
			}
			g.setStroke(new BasicStroke(next && pulse ? 3f : 2f));
			g.setColor(done ? new Color(90, 90, 90) : next ? new Color(0, 255, 90) : new Color(0, 170, 60));
			g.drawRect(x - 1, y - 1, 38, 34);
			g.setFont(FontManager.getRunescapeBoldFont());
			g.setColor(Color.BLACK);
			g.drawString(String.valueOf(k + 1), x + 2, y + 12);
			g.setColor(done ? new Color(170, 170, 170) : Color.WHITE);
			g.drawString(String.valueOf(k + 1), x + 1, y + 11);
		}
	}

	private void drawStepBanner(Graphics2D g, Rectangle cb, String title, String instruction, String progress)
	{
		final int x = cb.x;
		final int y = cb.y - 44;
		final int w = Math.max(200, cb.width);
		final int h = 40;
		g.setColor(new Color(0, 0, 0, 215));
		g.fillRoundRect(x, y, w, h, 8, 8);
		g.setStroke(new BasicStroke(2f));
		g.setColor(new Color(0, 200, 60));
		g.drawRoundRect(x, y, w, h, 8, 8);
		g.setFont(FontManager.getRunescapeBoldFont());
		g.setColor(Color.WHITE);
		g.drawString(title, x + 8, y + 16);
		if (progress != null)
		{
			// Right-aligned on the title row so it never pushes the instruction out of the box.
			final int pw = g.getFontMetrics().stringWidth(progress);
			g.setColor(new Color(140, 255, 140));
			g.drawString(progress, x + w - pw - 10, y + 16);
		}
		if (instruction != null)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(new Color(200, 255, 200));
			g.drawString(instruction, x + 8, y + 32);
		}
	}

	private void drawNotes(Graphics2D g, Rectangle cb)
	{
		// Solid dark panel so the text is readable over the busy bank behind it.
		g.setColor(new Color(0, 0, 0, 238));
		g.fillRoundRect(cb.x + 2, cb.y + 2, cb.width - 4, cb.height - 4, 10, 10);
		g.setStroke(new BasicStroke(2f));
		g.setColor(new Color(0, 200, 60));
		g.drawRoundRect(cb.x + 2, cb.y + 2, cb.width - 4, cb.height - 4, 10, 10);

		final int x = cb.x + 12;
		int y = cb.y + 24;
		g.setFont(FontManager.getRunescapeBoldFont());
		shadow(g, "You're ready. Here's how to build one:", x, y, new Color(0, 255, 90));

		g.setFont(FontManager.getRunescapeSmallFont());
		final String[] steps = {
			"1.  Open the Regear panel (icon on the right) and click New.",
			"2.  Name it, then add items: right-click an item -> Add to Regear.",
			"3.  Set how many slots show, and a pattern: Z, Vertical, Single or Custom.",
			"4.  Enable it (or Enable all), open the bank, click the green slots in order.",
		};
		for (String s : steps)
		{
			y += 20;
			shadow(g, s, x, y, Color.WHITE);
		}

		y += 26;
		g.setFont(FontManager.getRunescapeBoldFont());
		shadow(g, "Good to know:", x, y, new Color(0, 255, 90));
		g.setFont(FontManager.getRunescapeSmallFont());
		final String[] tips = {
			"- When a list finishes: Stop, Loop, or reset on bank close / inventory change.",
			"- Reset all lists, or reset a single list, whenever you want.",
			"- Hide this tutorial from the panel any time.",
		};
		for (String tip : tips)
		{
			y += 20;
			shadow(g, tip, x, y, new Color(210, 210, 210));
		}

		y += 30;
		final boolean on = System.currentTimeMillis() / 400 % 2 == 0;
		g.setFont(FontManager.getRunescapeBoldFont());
		shadow(g, "Click anywhere to finish the tutorial", x, y,
			on ? new Color(255, 95, 95) : new Color(255, 190, 190));
	}

	/** Draw text with a black drop-shadow for contrast over any background. */
	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private void drawProgress(Graphics2D g, Rectangle b, int withdrawn, int required)
	{
		final String text = withdrawn + "/" + required;
		g.setFont(FontManager.getRunescapeSmallFont());
		final int x = b.x + 1;
		final int y = b.y + b.height - 1;
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(new Color(120, 200, 255));
		g.drawString(text, x, y);
	}

	/**
	 * The canvas rectangle for a slot, shifted by the current bank scroll, or {@code null} if the cell
	 * is not fully within the scroll viewport (so the highlight is hidden until it is scrolled back).
	 */
	private static Rectangle slotRect(Rectangle view, int scrollY, int slot)
	{
		final int x = view.x + RegearBankController.slotToX(slot);
		final int y = view.y + RegearBankController.slotToY(slot) - scrollY;
		if (y < view.y || y + RegearBankController.ITEM_HEIGHT > view.y + view.height)
		{
			return null;
		}
		return new Rectangle(x, y, RegearBankController.ITEM_WIDTH, RegearBankController.ITEM_HEIGHT);
	}

	private void drawMissing(Graphics2D g, Rectangle r)
	{
		g.setColor(config.missingColor());
		g.setStroke(new BasicStroke(1f));
		g.drawRect(r.x, r.y, r.width, r.height);
		g.drawLine(r.x, r.y, r.x + r.width, r.y + r.height);
		g.drawLine(r.x + r.width, r.y, r.x, r.y + r.height);
	}

	private void drawLaneNumber(Graphics2D g, Rectangle b, int number)
	{
		final String text = Integer.toString(number);
		final Font prev = g.getFont();
		g.setFont(prev.deriveFont(Font.BOLD, 13f));
		final int x = b.x + 1;
		final int y = b.y + 12;
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(Color.WHITE);
		g.drawString(text, x, y);
		g.setFont(prev);
	}

	private void drawNextPreview(Graphics2D g, Rectangle b, int nextId)
	{
		final BufferedImage img = itemManager.getImage(nextId);
		if (img == null)
		{
			return;
		}
		final int size = 18;
		final int x = b.x + b.width - size;
		final int y = b.y + b.height - size;
		final Composite prev = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.7f));
		g.drawImage(img, x, y, size, size, null);
		g.setComposite(prev);
	}
}

package com.anonyser.regear;

/**
 * What a Regear lane does once it has advanced past the end of its list. Set once in the plugin
 * options and applied to every list; {@link #STOP} is the default.
 */
public enum CompletionBehavior
{
	/** Leave finished lanes empty; nothing more is shown. */
	STOP("Stop at end"),
	/** Wrap each finished lane back to its starting item and keep going. */
	LOOP("Loop to start"),
	/** Reset the whole sequence to the start whenever the bank closes. */
	RESET_ON_BANK_CLOSE("Reset on bank close"),
	/** Reset the whole sequence to the start on the next inventory change. */
	RESET_ON_INVENTORY_CHANGE("Reset on inv change"),
	/** Never auto-reset; only the panel's Reset button restarts the sequence. */
	MANUAL("Manual reset");

	private final String label;

	CompletionBehavior(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}
